import sys
def solve(m, n, grid):
    memo = {}
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]
    def dfs(r, c):
        if (r,c) in memo: return memo[(r,c)]
        best = 1
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0<=nr<m and 0<=nc<n and grid[nr][nc] > grid[r][c]:
                best = max(best, 1 + dfs(nr, nc))
        memo[(r,c)] = best; return best
    return str(max(dfs(r,c) for r in range(m) for c in range(n)))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    m, n = int(data[idx]), int(data[idx+1]); idx += 2
    grid = []
    for r in range(m):
        row = [int(data[idx+c]) for c in range(n)]; idx += n; grid.append(row)
    print(solve(m, n, grid))

